<?php
declare(strict_types=1);
require __DIR__ . '/bootstrap.php';

$siteSettings = getSiteSettings($pdo);
$eventId = max(0, (int)($_GET['event_id'] ?? 0));
if (!$currentUser) { header('Location: /account'); exit; }
$event = fetchEventById($pdo, $eventId);
$notes = fetchRideNotes($pdo, $eventId);
$role = strtolower((string)($currentUser['role'] ?? ''));
$preview = !empty($_GET['preview']) && $event && canAccessRideOrganiserEvent($currentUser, $event);
// The setup form starts with an unsaved draft when no notes row exists yet.
// Allow the same draft in authorised previews without publishing or saving it.
if ($event && $preview && !$notes) {
    $notes = ['status' => 'draft', 'intro_html' => '', 'ride_notes_html' => '', 'ctr_notes_html' => ''];
}
if (!$event || !$notes || (($notes['status'] ?? 'draft') !== 'published' && !$preview)) { http_response_code(404); $event = null; }
$rideBatch = $event ? mediaBatchFind($pdo, 'ride_notes_images', 'event', $eventId) : null;
$rideImages = $rideBatch ? mediaBatchImages($pdo, (int)$rideBatch['id']) : [];
$venue = $event && !empty($event['venue_id']) ? fetchVenueById($pdo,(int)$event['venue_id']) : null;
$venueBatch = $venue ? mediaBatchFind($pdo,'venue_images','venue',(int)$venue['id']) : null;
$venueImages = $venueBatch ? mediaBatchImages($pdo,(int)$venueBatch['id']) : [];
$emergencyPhone = $event ? rideEmergencyPhone($pdo, $event) : '';
$brand = trim((string)($siteSettings['company_name']??'')) ?: 'ILDRA';
$logo = trim((string)($siteSettings['ride_notes_email_header_image_url']??$siteSettings['sponsor_image_url']??''));
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>body{background:#f7f8f1}.head,.actions{background:#fff;border-bottom:1px solid #dbe5d8}.head .in{min-height:76px;display:flex;justify-content:center;align-items:center;gap:1rem}.brand{font-size:1.65rem;font-weight:800;color:#146118}.logo{max-height:76px;max-width:150px;object-fit:contain}.actions .in{padding:.6rem 0;display:flex;justify-content:flex-end;gap:.5rem}.card{border-radius:12px}.label{font-size:.76rem;color:#6c757d;text-transform:uppercase;font-weight:700}.main-img{width:100%;max-height:380px;object-fit:contain}.thumb{width:76px;height:58px;object-fit:cover}.print{background:#146118;color:#fff}@media print{.actions,.alert{display:none}.container{max-width:none!important;width:100%!important}}.rider-copy{overflow-wrap:anywhere}.rider-copy img{max-width:100%;height:auto}.ride-image-button{display:block;width:100%;border:0;padding:0;background:none;cursor:zoom-in}.main-img,.thumb{border-radius:8px}.rider-notes-footer h2{font-size:1.5rem}.rider-notes-footer h4{font-size:1.15rem}#ride-image-dialog{width:95vw;max-width:1400px;max-height:95vh;border:0;border-radius:12px;padding:1rem}#ride-image-dialog::backdrop{background:rgba(0,0,0,.7)}#ride-image-dialog img{display:block;max-width:100%;height:auto;margin:auto}.image-dialog-actions{position:sticky;top:0;background:white;padding-bottom:1rem}@media print{body.printing-ride-image>header,body.printing-ride-image>.actions,body.printing-ride-image>main{display:none!important}body.printing-ride-image #ride-image-dialog{position:static;display:block;width:100%;max-width:none;max-height:none;margin:0;padding:0}body.printing-ride-image .image-dialog-actions{display:none}body.printing-ride-image #ride-image-dialog img{max-width:100%;max-height:95vh;object-fit:contain}#ride-image-dialog::backdrop{background:transparent}}
</style></head><body>
<header class="head"><div class="container in"><?php if($logo): ?><img class="logo" src="<?php echo h($logo); ?>"><?php endif; ?><div class="brand"><?php echo h($brand); ?></div></div></header><div class="actions"><div class="container in"><a class="btn btn-sm btn-outline-secondary" href="/" target="_blank">Website Home</a><button class="btn btn-sm print" onclick="window.print()">Print</button></div></div>
<main class="container py-4"><?php if(!$event): ?><h1 class="h3">Rider Notes unavailable</h1><?php else: ?><?php if($preview && ($notes['status'] ?? 'draft') !== 'published'): ?><div class="alert alert-warning">Admin preview — these Rider Notes are <?php echo h((string)($notes['status'] ?? 'draft')); ?>.</div><?php endif; ?><section class="card bg-white p-4 mb-4"><div class="d-flex flex-column flex-md-row justify-content-between align-items-start gap-3 mb-4"><h1 class="h3 mb-0">Welcome to <?php echo h($event['title']); ?></h1><?php if($emergencyPhone !== ''): ?><div class="text-danger text-center text-md-end align-self-center align-self-md-start fw-bold flex-shrink-0"><div>Ride Emergency Number</div><a class="btn btn-danger fs-3 fw-bold mt-1 px-3 py-2" href="tel:<?php echo h(preg_replace('/[^0-9+]/', '', $emergencyPhone)); ?>"><?php echo h($emergencyPhone); ?></a></div><?php endif; ?></div><div class="row g-3"><div class="col-md-3"><div class="label">Ride Name</div><strong><?php echo h($event['title']); ?></strong></div><div class="col-md-3"><div class="label">Venue</div><strong><?php echo h($venue['name']??$event['venue']??'—'); ?><?php echo !empty($venue['postcode'])?' · '.h($venue['postcode']):''; ?></strong></div><div class="col-md-2"><div class="label">Date</div><strong><?php echo !empty($event['event_date']) ? h((new DateTimeImmutable((string)$event['event_date']))->format('jS M Y')) : '—'; ?></strong></div><div class="col-6 col-md-2"><div class="label">Start Time</div><strong><?php echo h($event['start_time']??'—'); ?></strong></div><div class="col-6 col-md-2"><div class="label">Last Ride Out</div><strong><?php echo h($event['end_time']??'—'); ?></strong></div></div><hr><h2 class="h4 mb-3">Rider Information</h2><div class="row g-4 align-items-start"><div class="<?php echo $rideImages ? 'col-12 col-md-8' : 'col-12'; ?> rider-copy"><?php echo render_wysiwyg((string)($notes['ride_notes_html']??'')); ?></div><?php if($rideImages): ?><div class="col-12 col-md-4"><button type="button" class="ride-image-button" id="expand-ride-image" aria-label="Expand Rider Notes image"><img class="main-img" src="<?php echo h(mediaBatchImageUrl($rideBatch,$rideImages[0],'md')); ?>" alt="<?php echo h($rideImages[0]['alt_text'] ?: 'Rider Notes image'); ?>"></button><div class="small text-muted mt-2">Click image to enlarge and print.</div></div><?php endif; ?></div><?php if(rideNotesPdfAttachment($notes)): ?><div class="mt-4"><a class="btn btn-outline-success" target="_blank" rel="noopener" href="<?php echo h(rideNotesPdfUrl((string)$notes['pdf_filename'])); ?>"><i class="fa-solid fa-file-pdf"></i> Download Rider Notes PDF</a></div><?php endif; ?></section>
<?php if($venue): ?><section class="card bg-white p-4 mb-4"><h2 class="h4">Venue</h2><div class="row g-4"><?php if($venueImages): ?><div class="col-md-5"><img class="main-img" src="<?php echo h(mediaBatchImageUrl($venueBatch,$venueImages[0],'md')); ?>"><?php foreach(array_slice($venueImages,1)as$image): ?><a href="<?php echo h(mediaBatchImageUrl($venueBatch,$image,'original')); ?>" target="_blank"><img class="thumb m-1" src="<?php echo h(mediaBatchImageUrl($venueBatch,$image,'xs')); ?>"></a><?php endforeach; ?></div><?php endif; ?><div class="<?php echo $venueImages?'col-md-7':'col-12'; ?>"><?php if(trim((string)($venue['address']??''))!=='' || trim((string)($venue['postcode']??''))!==''): ?><div class="mb-3"><div class="label">Address</div><?php echo nl2br(h(trim((string)($venue['address']??'')))); ?><?php if(trim((string)($venue['postcode']??''))!==''): ?><?php echo trim((string)($venue['address']??'')) !== '' ? ', ' : ''; ?><?php echo h(trim((string)$venue['postcode'])); ?><?php endif; ?></div><?php endif; ?><?php if(trim((string)($venue['notes']??''))!==''): ?><h3 class="h5">Venue Notes</h3><?php echo render_wysiwyg((string)$venue['notes']); ?><?php endif; ?><?php if(trim((string)($venue['directions']??''))!==''): ?><div class="mt-3"><h3 class="h5">Directions</h3><?php echo render_wysiwyg((string)$venue['directions']); ?></div><?php endif; ?></div></div><?php if(!empty($venue['what3words'])): ?><div class="mt-3"><span class="label">What3Words</span> <a href="https://what3words.com/<?php echo h(rawurlencode($venue['what3words'])); ?>" target="_blank" rel="noopener noreferrer"><?php echo h('///'.$venue['what3words']); ?></a></div><?php endif; ?><?php if(!empty($venue['google_url'])): ?><a class="btn btn-sm btn-outline-secondary mt-3" href="<?php echo h($venue['google_url']); ?>" target="_blank"><i class="fa-solid fa-map-location-dot"></i> View on Google Maps</a><?php endif; ?></section><?php endif; ?><?php if(trim((string)($siteSettings['ride_notes_footer_html']??''))!==''): ?><section class="card bg-white p-4 mb-4 rider-notes-footer"><?php echo render_wysiwyg((string)$siteSettings['ride_notes_footer_html']); ?></section><?php endif; ?><?php if(trim((string)($notes['ctr_notes_html']??''))!==''): ?><section class="card bg-white p-4"><h2 class="h4">Competitive Riders</h2><?php echo render_wysiwyg((string)$notes['ctr_notes_html']); ?></section><?php endif; ?><div class="card bg-white p-4 mt-4 text-center"><h2 class="h2 fw-bold text-success mb-0">Enjoy your ride</h2></div><?php endif; ?></main>
<?php if($event && $rideImages): ?>
<dialog id="ride-image-dialog" aria-label="Rider Notes image enlarged"><div class="image-dialog-actions"><button type="button" id="print-ride-image" class="btn btn-success">Print image</button> <button type="button" id="close-ride-image" class="btn btn-outline-secondary">Close</button></div><img src="<?php echo h(mediaBatchImageUrl($rideBatch,$rideImages[0],'original')); ?>" alt="<?php echo h($rideImages[0]['alt_text'] ?: 'Rider Notes image'); ?>"></dialog>
<script>
(() => {
    const dialog = document.getElementById('ride-image-dialog');
    document.getElementById('expand-ride-image').addEventListener('click', () => dialog.showModal());
    document.getElementById('close-ride-image').addEventListener('click', () => dialog.close());
    document.getElementById('print-ride-image').addEventListener('click', async () => {
        const image = dialog.querySelector('img');
        try { await image.decode(); } catch { return; }
        document.body.classList.add('printing-ride-image');
        window.print();
    });
    window.addEventListener('afterprint', () => document.body.classList.remove('printing-ride-image'));
})();
</script>
<?php endif; ?>
</body></html>
